for n in [0, 1, 4]:
    sequential = 0
    for i in range(n):
        sequential = sequential + 1
    for j in range(n):
        sequential = sequential + 1

    rectangular = 0
    triangular = 0
    for i in range(n):
        for j in range(n):
            rectangular = rectangular + 1
        for j in range(i):
            triangular = triangular + 1
    print(n, sequential, rectangular, triangular)

for n in [6, 0]:
    count = 0
    for i in range(n):
        for j in range(i):
            count = count + 1
    print(n, count)
